// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/v1/backlog", wrapper.GetInboxBacklog)

	router.Get(options.BaseURL+"/v1/inbox-items", wrapper.ListInboxItems)

	router.Post(options.BaseURL+"/v1/inbox-items", wrapper.CreateInboxItem)

	router.Get(options.BaseURL+"/v1/inbox-items/:itemId", wrapper.GetInboxItem)

	router.Post(options.BaseURL+"/v1/inbox-items/:itemId/resolve", wrapper.ResolveInboxItem)

	router.Post(options.BaseURL+"/v1/inbox-items/:itemId/discard", wrapper.DiscardInboxItem)

	router.Post(options.BaseURL+"/v1/inbox-items/:itemId/human-review", wrapper.CreateHumanReview)

	router.Post(options.BaseURL+"/v1/inbox-items/:itemId/human-review/resolve", wrapper.ResolveHumanReview)

	router.Get(options.BaseURL+"/v1/inbox-items/:itemId/processing-attempts", wrapper.ListProcessingAttempts)

	router.Post(options.BaseURL+"/v1/inbox-items/:itemId/processing-attempts", wrapper.CreateProcessingAttempt)

	router.Patch(options.BaseURL+"/v1/inbox-items/:itemId/processing-attempts/:attemptId", wrapper.UpdateProcessingAttempt)

	router.Put(options.BaseURL+"/v1/inbox-items/:itemId/processing-attempts/:attemptId/runtime", wrapper.RecordAttemptRuntime)

	router.Post(options.BaseURL+"/v1/media", wrapper.UploadMedia)

	router.Get(options.BaseURL+"/v1/media/:sha256", wrapper.GetMedia)

	router.Get(options.BaseURL+"/v1/stale-processing-attempts", wrapper.ListStaleProcessingAttempts)

}
